#include <bits/stdc++.h>
using namespace std;

const int N = 100, D = 31, MOD = 1000000007;

int base, index_pos, digits_arr[N];
long long number_input;

struct MatrixType {
    long long mat[D][D];

    MatrixType() {
        for (int i = 0; i <= base; i++) {
            for (int j = 0; j <= base; j++) {
                mat[i][j] = 0;
            }
        }
    }

    MatrixType operator*(const MatrixType& other) const {
        MatrixType res;
        for (int i = 0; i <= base; i++) {
            for (int j = 0; j <= base; j++) {
                for (int k = 0; k <= base; k++) {
                    res.mat[i][j] = (res.mat[i][j] + mat[i][k] * other.mat[k][j]) % MOD;
                }
            }
        }
        return res;
    }
} base_mats[N];

MatrixType rotate_shift(int shift_value) {
    shift_value = (shift_value + base) % base;
    MatrixType m;
    for (int i = 0; i < base; i++) {
        m.mat[i][(i + shift_value) % base] = 1;
    }
    m.mat[base][base] = 1;
    return m;
}

void initialize_matrices() {
    for (int i = 1; i < base; i++) {
        base_mats[0].mat[i][i] = 1;
    }
    base_mats[0].mat[base][0] = 1;
    base_mats[0].mat[base][base] = 2;
    base_mats[0].mat[0][base] = -1;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> number_input >> base;
    for (index_pos = 0; number_input > 0; index_pos++, number_input /= base) {
        digits_arr[index_pos] = number_input % base;
    }
    initialize_matrices();
    for (int i = 1; i < index_pos; i++) {
        base_mats[i] = rotate_shift(0);
        for (int j = 0; j < base; j++) {
            base_mats[i] = base_mats[i] * base_mats[i - 1] * rotate_shift(1);
        }
    }
    MatrixType answer = rotate_shift(0);
    for (int i = index_pos - 1; i >= 0; i--) {
        for (int j = 0; j < digits_arr[i]; j++) {
            answer = answer * base_mats[i] * rotate_shift(1);
        }
    }
    cout << (answer.mat[base][base] + MOD) % MOD;
}
